function notionId(value) {
  if (typeof value !== "string") throw Error("A Notion ID is missing.");
  const compact = value.replace(/-/g, "").toLowerCase();
  if (!/^[a-f0-9]{32}$/.test(compact)) throw Error("A Notion ID is invalid.");
  return compact.replace(/^(.{8})(.{4})(.{4})(.{4})(.{12})$/, "$1-$2-$3-$4-$5");
}

function settings(dataSource, author, at) {
  if (typeof author !== "string" || !/^urn:li:person:[A-Za-z0-9_-]{1,80}$/.test(author)) {
    throw Error("Set the LinkedIn person URN you intend to post as.");
  }
  const date = new Date(at);
  if (!Number.isFinite(date.getTime())) throw Error("The schedule timestamp is unavailable.");
  return { dataSource: notionId(dataSource), author, date: date.toISOString().slice(0, 10) };
}

function checksForDate(config) {
  return {
    filter: { property: "Date", date: { equals: config.date } },
    sorts: [{ timestamp: "created_time", direction: "ascending" }],
    page_size: 100,
  };
}

const { dataSource, author } = {
  dataSource: "YOUR_NOTION_DATA_SOURCE_ID",
  author: "YOUR_LINKEDIN_PERSON_URN",
};
const config = settings(dataSource, author, $input.first().json.timestamp);
return [{ json: { ...config, query: checksForDate(config) }, pairedItem: { item: 0 } }];

function checkMember(member, author) {
  if ("urn:li:person:" + member?.sub !== author)
    throw Error("LinkedIn authorization does not match the configured member.");
}

const config = $("Set Notion and LinkedIn IDs").first().json;
checkMember($input.first().json.body, config.author);
return [{ json: config, pairedItem: { item: 0 } }];

