}

function checkedPages(pages, config) {
  const ids = new Set();
  const pending = [];
  for (const page of pages) {
    const pageId = notionId(page?.id);
    if (
      page.object !== "page" ||
      page.archived === true ||
      page.in_trash === true ||
      page.parent?.type !== "data_source_id" ||
      notionId(page.parent.data_source_id) !== config.dataSource ||
      page.properties?.Date?.type !== "date" ||
      page.properties.Date.date?.start !== config.date ||
      page.properties.Date.date.end !== null ||
      page.properties?.Status?.type !== "select" ||
      !Number.isFinite(Date.parse(page.created_time)) ||
      ids.has(pageId)
    ) {
      throw Error("Notion returned an unexpected page for the configured date or data source.");
    }
    ids.add(pageId);
    if (page.properties.Status.select?.name !== "Published") {
      pending.push({
        pageId,
        created: page.created_time,
        key: "linkedin-notion-page:" + config.dataSource + ":" + pageId,
      });
    }
  }
  return pending.sort(
    (a, b) => a.created.localeCompare(b.created) || a.pageId.localeCompare(b.pageId),
  );
}

async function collectNotion(fetchPage, label) {
  const rows = [];
  const seen = new Set();
  let cursor;
  for (let index = 0; index < 10; index++) {
    const page = await fetchPage(cursor);
    if (
      !Array.isArray(page?.results) ||
      typeof page.has_more !== "boolean" ||
      page.results.length > 100 ||
      page.request_status?.type === "incomplete"
    ) {
      throw Error("Notion returned an invalid " + label + " list.");
    }
    rows.push(...page.results);
    if (page.has_more === false && page.next_cursor === null) return rows;
    if (
      !page.has_more ||
      typeof page.next_cursor !== "string" ||
      !page.next_cursor ||
      seen.has(page.next_cursor)
    ) {
      throw Error("Notion returned an incomplete " + label + " list.");
    }
    cursor = page.next_cursor;
    seen.add(cursor);
  }
  throw Error("Notion returned more than ten pages of " + label + ".");
}

const parts = $input.all();
let offset = 0;
const collected = await collectNotion(() => {
  const response = parts[offset++]?.json;
  if (response?.statusCode !== 200) throw Error("Notion did not confirm the scheduled posts page.");
  return response.body;
}, "scheduled posts");
if (offset !== parts.length) throw Error("Unexpected extra pages from Notion.");

const config = $("Set Notion and LinkedIn IDs").first().json;
return checkedPages(collected, config).map((row) => ({ json: row, pairedItem: { item: 0 } }));

function notionId(value) {
  if (typeof value !== "string") throw Error("A Notion ID is missing.");
  const compact = value.replace(/-/g, "").toLowerCase();
  if (!/^[a-f0-9]{32}$/.test(compact)) throw Error("A Notion ID is invalid.");
  return compact.replace(/^(.{8})(.{4})(.{4})(.{4})(.{12})$/, "$1-$2-$3-$4-$5");
}

function hostedNotionImage(file) {
  const url = file?.url;
  const expires = Date.parse(file?.expiry_time);
  if (
    typeof url !== "string" ||
    url.length > 8000 ||
    !Number.isFinite(expires) ||
    expires <= Date.now() ||
    /[\s\\#]/.test(url) ||
    !/^https:\/\/(?:(?:prod-files-secure|secure\.notion-static\.com)\.s3(?:[.-][a-z0-9-]+)?\.amazonaws\.com\/[^?]+|s3(?:[.-][a-z0-9-]+)?\.amazonaws\.com\/(?:prod-files-secure|secure\.notion-static\.com)\/[^?]+)\?/i.test(
      url,
    )
  ) {
    throw Error("The first image must be an unexpired, Notion-hosted file URL.");
  }
  return url;
}

function notionPost(blocks, pageId) {
  const texts = [];
  const ids = new Set();
  let firstImage;
  for (const block of blocks) {
    const id = notionId(block?.id);
    if (
      block.object !== "block" ||
      block.parent?.type !== "page_id" ||
      notionId(block.parent.page_id) !== pageId ||
      ids.has(id) ||
      typeof block.type !== "string"
    ) {
      throw Error("Notion returned a block from a different page or repeated a block.");
    }
    ids.add(id);
    const data = block[block.type];
    if (block.type === "image" && data?.type === "file" && firstImage === undefined)
      firstImage = data.file;
    else if (
      ["child_page", "child_database"].includes(block.type) &&
      typeof data?.title === "string"
    )
      texts.push(data.title);
    else if (block.type !== "image") {
      const text = data?.rich_text ?? data?.text;
      if (Array.isArray(text))
        texts.push(text.map((part) => part?.plain_text ?? part?.text?.content ?? "").join(""));
    }
  }
  const text = texts
    .reduce(
      (combined, line, index) =>
        index ? combined + (line.startsWith("-") ? "\n\n" : "\n") + line : line,
      "",
    )
    .trim();
  if (!text || text.length > 3000)
    throw Error("Provide one to 3,000 characters of text in the post page.");
  return { text, imageUrl: hostedNotionImage(firstImage) };
}

