const parts = $input.all();
let offset = 0;
const collected = await collectNotion(() => {
  const response = parts[offset++]?.json;
  if (response?.statusCode !== 200) throw Error("Notion did not confirm the page blocks page.");
  return response.body;
}, "page blocks");
if (offset !== parts.length) throw Error("Unexpected extra pages from Notion.");

const row = $("Select the exact Notion page").itemMatching(0).json;
