  {
    json: { ...notionPost(collected, row.pageId), row, author: config.author },
    pairedItem: { item: 0 },
  },
];

function verifyBytes(bytes, mimeType) {
  const mime = typeof mimeType === "string" ? mimeType.split(";")[0].trim().toLowerCase() : "";
  const png = [137, 80, 78, 71, 13, 10, 26, 10].every((byte, index) => bytes[index] === byte);
  const jpeg = bytes[0] === 255 && bytes[1] === 216 && bytes[2] === 255;
  const gif =
    bytes[0] === 71 &&
    bytes[1] === 73 &&
    bytes[2] === 70 &&
    bytes[3] === 56 &&
    [55, 57].includes(bytes[4]) &&
    bytes[5] === 97;
  if (
    bytes.length < 16 ||
    bytes.length > 10 * 1024 * 1024 ||
    !(
      (mime === "image/png" && png) ||
      (mime === "image/jpeg" && jpeg) ||
      (mime === "image/gif" && gif)
    )
  ) {
    throw Error("The Notion file must be a JPEG, PNG, or GIF up to 10 MiB.");
  }
}

const data = $input.first();
const plan = $("Compose this page’s post").itemMatching(0).json;
verifyBytes(await helpers.getBinaryDataBuffer(0, "data"), data.binary?.data?.mimeType);
return [{ json: plan, binary: data.binary, pairedItem: { item: 0 } }];

function imageUpload(body, status) {
  const value = body?.value;
  const image = value?.image;
  const url = value?.uploadUrl;
  const expiry = value?.uploadUrlExpiresAt;
  if (
    status !== 200 ||
    typeof image !== "string" ||
    !/^urn:li:image:[A-Za-z0-9_-]{1,150}$/.test(image) ||
    typeof url !== "string" ||
    !Number.isSafeInteger(expiry) ||
    expiry <= Date.now() ||
    /[\s#\\]/.test(url) ||
    !url.startsWith(
      "https://www.linkedin.com/dms-uploads/" +
        image.slice("urn:li:image:".length) +
        "/uploaded-image/0?",
    )
  ) {
    throw Error("LinkedIn did not confirm an upload slot for that image.");
  }
  return {
    image,
    uploadUrl: url,
    statusUrl: "https://api.linkedin.com/rest/images/" + encodeURIComponent(image),
  };
}

const { body, statusCode } = $input.first().json;
const { json: plan, binary } = $("Validate the Notion photo bytes").itemMatching(0);
return [{ json: { ...plan, ...imageUpload(body, statusCode) }, binary, pairedItem: { item: 0 } }];

const asset = $("Verify the upload slot").itemMatching(0).json;
const previous = $input.first().json.count ?? 0;
return [{ json: { ...asset, count: previous + 1 }, pairedItem: { item: 0 } }];

function imageAvailable(body, status, image, author, count) {
  if (status !== 200 || body?.id !== image || body.owner !== author) {
    throw Error("LinkedIn did not confirm the same uploaded image and member.");
  }
  if (body.status === "AVAILABLE") return true;
  if (!["WAITING_UPLOAD", "PROCESSING"].includes(body.status) || count >= 10) {
    throw Error("LinkedIn did not finish processing the image. No post was attempted.");
  }
  return false;
}

function photoPost(author, commentary, image) {
  const text = commentary.replace(/[\\()[\]{}<>@|~_*]/gu, (character) => "\\" + character);
  return {
    author,
    commentary: text,
    visibility: "PUBLIC",
    lifecycleState: "PUBLISHED",
    distribution: {
      feedDistribution: "MAIN_FEED",
      targetEntities: [],
      thirdPartyDistributionChannels: [],
    },
    content: { media: { id: image } },
    isReshareDisabledByAuthor: false,
  };
}

const { body, statusCode } = $input.first().json;
const asset = $("Count image status checks").itemMatching(0).json;
const ready = imageAvailable(body, statusCode, asset.image, asset.author, asset.count);
return [
  {
    json: {
      ...asset,
      ready,
      post: ready ? photoPost(asset.author, asset.text, asset.image) : null,
    },
    pairedItem: { item: 0 },
  },
];

function postReceipt(status, headers) {
  const postId = headers?.["x-restli-id"];
  if (
    status !== 201 ||
    typeof postId !== "string" ||
    !/^urn:li:(?:share|ugcPost):[1-9]\d*$/.test(postId)
  ) {
    throw Error(
      "LinkedIn did not confirm publication. Check the profile before clearing the reservation.",
    );
  }
  return postId;
}

const data = $input.first().json;
const result = $("Verify the image status").itemMatching(0).json;
return [
  {
    json: { row: result.row, postId: postReceipt(data.statusCode, data.headers) },
    pairedItem: { item: 0 },
  },
];

function notionId(value) {
  if (typeof value !== "string") throw Error("A Notion ID is missing.");
  const compact = value.replace(/-/g, "").toLowerCase();
  if (!/^[a-f0-9]{32}$/.test(compact)) throw Error("A Notion ID is invalid.");
  return compact.replace(/^(.{8})(.{4})(.{4})(.{4})(.{12})$/, "$1-$2-$3-$4-$5");
}

function confirmNotion(page, pageId, dataSource) {
  if (
    page?.object !== "page" ||
    notionId(page?.id) !== pageId ||
    page.parent?.type !== "data_source_id" ||
    notionId(page.parent.data_source_id) !== dataSource ||
    page.properties?.Status?.select?.name !== "Published"
  ) {
    throw Error(
      "Notion did not confirm Published on the same page. The LinkedIn post must not be sent again.",
    );
  }
}

const { body, statusCode } = $input.first().json;
if (statusCode !== 200) throw Error("Notion did not confirm the status update.");
const { row, postId } = $("Confirm the LinkedIn post").itemMatching(0).json;
const config = $("Set Notion and LinkedIn IDs").first().json;
confirmNotion(body, row.pageId, config.dataSource);
return [{ json: { status: "published", pageId: row.pageId, postId }, pairedItem: { item: 0 } }];
